with ranked as (select * from (select *, row_number() over (partition by brand, supplier_id order by cost asc, id asc) as rn from products) ranked where rn = 1) select case when cost >= 680 then 'HIGH' else 'LOW' end as cost_tier, supplier_id, sum(case when category = 'Home' then cost else 0 end) as home_cost, stddev_samp(price) as price_stddev, size(collect_set(brand)) as num_brands, grouping_id() as grouping_level from ranked group by rollup (case when cost >= 680 then 'HIGH' else 'LOW' end, supplier_id) order by home_cost desc
